describe('File Upload - Remove File from Queue', () => {
  beforeEach(() => {
    cy.visit('/upload');
    cy.get('[data-testid="file-input"]').should('be.visible');
  });

  it('should remove a single file from the upload queue before submission', () => {
    const fileName = 'test-document.pdf';

    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-document.pdf', { force: true });

    cy.get('[data-testid="upload-queue-item"]').should('have.length', 1);
    cy.get('[data-testid="upload-queue-item"]').should('contain', fileName);

    cy.get('[data-testid="remove-file-btn"]').first().click();

    cy.get('[data-testid="upload-queue-item"]').should('have.length', 0);
    cy.get('[data-testid="queue-empty-message"]').should('be.visible');

    cy.get('[data-testid="submit-btn"]').should('be.disabled');
  });

  it('should remove a specific file from multiple files in the queue', () => {
    const file1 = 'document1.pdf';
    const file2 = 'document2.docx';
    const file3 = 'document3.xlsx';

    cy.get('[data-testid="file-input"]').selectFile([
      'cypress/fixtures/document1.pdf',
      'cypress/fixtures/document2.docx',
      'cypress/fixtures/document3.xlsx'
    ], { force: true });

    cy.get('[data-testid="upload-queue-item"]').should('have.length', 3);

    cy.get('[data-testid="upload-queue-item"]').eq(1).within(() => {
      cy.get('[data-testid="remove-file-btn"]').click();
    });

    cy.get('[data-testid="upload-queue-item"]').should('have.length', 2);
    cy.get('[data-testid="upload-queue-item"]').should('contain', file1);
    cy.get('[data-testid="upload-queue-item"]').should('contain', file3);
    cy.get('[data-testid="upload-queue-item"]').should('not.contain', file2);

    cy.get('[data-testid="submit-btn"]').should('not.be.disabled');
  });

  it('should handle removing all files one by one from the queue', () => {
    cy.get('[data-testid="file-input"]').selectFile([
      'cypress/fixtures/file1.txt',
      'cypress/fixtures/file2.txt'
    ], { force: true });

    cy.get('[data-testid="upload-queue-item"]').should('have.length', 2);

    cy.get('[data-testid="remove-file-btn"]').first().click();
    cy.get('[data-testid="upload-queue-item"]').should('have.length', 1);

    cy.get('[data-testid="remove-file-btn"]').first().click();
    cy.get('[data-testid="upload-queue-item"]').should('have.length', 0);

    cy.get('[data-testid="queue-empty-message"]').should('be.visible');
    cy.get('[data-testid="submit-btn"]').should('be.disabled');
  });

  it('should prevent submission when all files are removed from queue', () => {
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-file.pdf', { force: true });

    cy.get('[data-testid="upload-queue-item"]').should('have.length', 1);
    cy.get('[data-testid="submit-btn"]').should('not.be.disabled');

    cy.get('[data-testid="remove-file-btn"]').click();

    cy.get('[data-testid="upload-queue-item"]').should('have.length', 0);
    cy.get('[data-testid="submit-btn"]').should('be.disabled');
    cy.get('[data-testid="submit-btn"]').click({ force: true });

    cy.get('[data-testid="error-message"]').should('contain', 'Please add at least one file');
  });

  it('should update file count indicator when removing files', () => {
    cy.get('[data-testid="file-input"]').selectFile([
      'cypress/fixtures/file1.pdf',
      'cypress/fixtures/file2.pdf',
      'cypress/fixtures/file3.pdf'
    ], { force: true });

    cy.get('[data-testid="file-count"]').should('contain', '3');

    cy.get('[data-testid="remove-file-btn"]').first().click();
    cy.get('[data-testid="file-count"]').should('contain', '2');

    cy.get('[data-testid="remove-file-btn"]').first().click();
    cy.get('[data-testid="file-count"]').should('contain', '1');
  });
});
